from shopkit.invoicing.models import Invoice, InvoiceLine
from shopkit.orders.models import Order


def build_invoice(order: Order) -> Invoice:
    """Construct an Invoice object from an Order."""
    lines = [
        InvoiceLine(description=f"{l.qty} x {l.sku}", amount_cents=l.total_cents)
        for l in order.lines
    ]
    subtotal = order.subtotal_cents
    discount = order.discount_cents
    total = order.total_cents
    return Invoice(
        order_id=order.id,
        currency=order.currency,
        lines=lines,
        subtotal_cents=subtotal,
        discount_cents=discount,
        total_cents=total,
    )


def render_invoice(invoice: Invoice) -> str:
    """Render the invoice as a text string."""
    lines = []
    lines.append(f"Invoice for {invoice.order_id}")
    lines.append("-" * 40)
    for line in invoice.lines:
        lines.append(f"{line.description:<30} {line.amount_cents:>10} cents")
    lines.append("-" * 40)
    lines.append(f"{'Subtotal':<30} {invoice.subtotal_cents:>10} cents")
    if invoice.discount_cents > 0:
        lines.append(f"{'Discount':<30} -{invoice.discount_cents:>10} cents")
    lines.append(f"{'Total':<30} {invoice.total_cents:>10} cents")
    return "\n".join(lines)
